import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"TikTools 4.2.1-rc.2","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.2","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"8629ea4d7bc6121c97cd9be2424cfc501762bd182fff181eb9d168e1fc06e5ae","order":20},"headers":[],"relativePath":"fr/releases/4.2.1-rc.2.md","filePath":"fr/releases/4.2.1-rc.2.md","lastUpdated":1794611623000}'),n={name:"fr/releases/4.2.1-rc.2.md"};function o(s,e,c,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objectif, état et prérequis <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objectif, état et prérequis {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Utilisez les notes historiques RC2 pour comprendre la correction des lectures Changes concurrentes reproduites dans RC1. Le rapport candidat couvre les paquets Linux AppImage, DEB et portables compilés localement lorsque Actions était désactivé. Il n’établit ni la disponibilité actuelle des téléchargements ni l’existence d’un nouveau paquet Windows compilé. Choisissez les ressources dans la <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">liste des versions</a>, conservez leur fichier de sommes de contrôle et testez avec un profil isolé.</p><p>La récupération Cloud et la collaboration restent expérimentales. La recherche de pseudonymes dépend toujours du serveur <code>6a69c99</code> et de la migration <code>20261113000001_remote_invitation_recipients.sql</code> ; le paquet de l’application ne déploie pas ces changements.</p><h2 id="correction-and-expected-behavior" tabindex="-1">Correction et comportement attendu <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;Correction et comportement attendu {#correction-and-expected-behavior}&quot;">​</a></h2><p>Les listes Changes/conflits et la sélection de protocole partagent l’observation du protocole au lieu de réserver le créneau de mutation du produit. Les lectures de la barre d’outils et du panneau peuvent se terminer pendant qu’une opération de journal de paquet sans rapport occupe ce créneau. Les barrières d’écriture, l’isolation des comptes et les décisions explicites de migration sont conservées.</p><p>La vérification du compte rejette la déconnexion, les transitions en attente et les sessions de remplacement. Lire une comparaison locale ne restaure pas les identifiants et ne lance pas de requête Cloud. En cas d’échec, l’interface affiche la raison native et une action de rechargement local ; cette nouvelle tentative n’envoie, ne télécharge et ne résout aucun enregistrement.</p><h2 id="check-the-candidate" tabindex="-1">Vérifier la version candidate <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;Vérifier la version candidate {#check-the-candidate}&quot;">​</a></h2><ol><li>Notez la version affichée <code>4.2.1-rc.2</code> et ouvrez Plugins → Changes dans un profil isolé.</li><li>Ouvrez ou rechargez la comparaison depuis la barre d’outils et le panneau. Un échec de chargement doit conserver sa raison plutôt qu’indiquer que tout est synchronisé.</li><li>Utilisez la nouvelle tentative locale et confirmez qu’elle recharge la comparaison sans modifier les files en attente ni appliquer d’enregistrements distants.</li><li>Notez séparément les transitions de compte/session. Comparez avec la <a href="./4.2.1-rc.1.html">procédure de migration RC1</a> en reproduisant un profil concerné.</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">Validation enregistrée et récupération <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;Validation enregistrée et récupération {#recorded-validation-and-recovery}&quot;">​</a></h2><p>Le rapport original décrit une régression déterministe à 32 lecteurs, des vérifications CloudAuth/synchronisation/natif/interface et le démarrage de l’AppImage optimisée avec un profil isolé vide. Les vérifications du contenu des installateurs et des archives portables ont été consignées. Ce démarrage n’a testé ni la synchronisation en production avec un compte connecté ni la lecture multimédia.</p><p>Le SHA-256 historique de l’AppImage était <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code>. Il identifie ce fichier consigné ; utilisez la somme de contrôle jointe à la ressource que vous téléchargez réellement.</p><p>Si le chargement échoue encore, conservez version, erreur native et identifiant de requête, puis utilisez <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>. Préservez les modifications en attente et conflits. À RC2, Automations utilisait toujours une référence locale, les travaux des sections Variables et Overlay étaient inachevés et le détenteur historique du verrou SQLite restait non identifié. Ces notes n’affirment pas que la route de recherche de personnes absente d’un ancien serveur a depuis été déployée.</p><p>Le <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">rapport de version original</a> est conservé comme preuve datée. Revenez à l’<a href="./">index des versions</a>.</p>',14)])])}const f=t(n,[["render",o]]);export{h as __pageData,f as default};
